row=np.array([ix[s] for s in sets]); tg=np.array([int(q['target'])-1 for q in r]); y=np.array([int(q['rating']) for q in r])
def make(big):
    RM=rules(big); M=np.vstack([RM,IM]); sz=M.sum(1)
    return RM,M,sz
def nll(pred):
    p=np.clip(pred,1e-9,1-1e-9); return -(y*np.log(p)+(1-y)*np.log(1-p)).sum()
def model(theta,big,variant):
    RM,M,sz=CACHE[big]; nr=len(RM)
    lam=1/(1+np.exp(-theta[0])); sig=np.exp(theta[1]); noise=0.1; beta=1.0; lapse=0; base=0
    if variant=='noise': noise=1/(1+np.exp(-theta[2]))
    if variant=='beta': beta=np.exp(theta[2])
    if variant=='lapse': lapse=1/(1+np.exp(-theta[2])); base=1/(1+np.exp(-theta[3]))
    isz=sz[nr:]; le=np.log(isz/sig**2)-isz/sig; le=le-logsumexp(le)
    if variant=='uniform': le=np.full(len(isz),-np.log(len(isz)))
    lp=np.concatenate([np.full(nr,np.log(lam/nr)),np.log(1-lam)+le])
    ell=np.log((1-noise)*M/sz[:,None]**beta*(1 if beta==1 else 1)+noise/100) if beta==1 else beta*np.log((1-noise)*M/sz[:,None]+noise/100)
    out=np.zeros(len(y))
